RoleManagement = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=RoleManagement]");
		api.addToMetaCache([
			{
        "Name": "AppSecurity",
        "Types": [
            [meta[AppSecurity/Role]]
        ]
    }
		]);
		await RoleManagement.setupRoleGrid(app, container);
	},

	setupRoleGrid: async function (app, container) {
		var config = {
			endpoint: "AppSecurity/Role",
			odataAppend: "?$filter=AppId eq " + app.Id,
			sort: {
				field: "Name",
				dir: "asc"
			},
            pageSize: 50
		};
		var ds = await model.getDatasource(config);
		var roleGrid = new GridWidget(container, ds);
		roleGrid.groupable = false;
		roleGrid.filterable = true;
		roleGrid.sortable = true;
		roleGrid.toolbar = [{ template: "<button class='btn btn-primary' name='createRole'><span class='k-icon k-i-plus'></span>[resource_displayname[NewRole]]</button>" }];
		roleGrid.columns = [
			{
				field: "Name",
				title: "[resource_shortdisplayname[Name]]"
			}
		];
	roleGrid.commands.push({
		name: "save",
		icon: "k-i-save",
		text: "[resource_displayname[save]]"
	});

	roleGrid.commands.push({
		name: "destroy",
		icon: "k-i-trash",
		text: "[resource_displayname[delete]]"
	});
		var roleDetails = $("template[name=roleDetails]", container).html();
			roleGrid.detailTemplate = function () { return roleDetails; };
			roleGrid.detailExpand = function (e) {
				return RoleManagement.expandRole(e, app, roleGrid, container);
			};
			
			await roleGrid.init();

			roleGrid.gridElement
				.off("click.roleManagement", "button[name=save]")
				.on(
					"click.roleManagement",
					"button[name=save]",
					async function (e) {
						console.log("Role save clicked");
						await RoleManagement.save(e, roleGrid);
					}
				);

			roleGrid.gridElement
				.off("click.roleManagement", "button[name=destroy]")
				.on(
					"click.roleManagement",
					"button[name=destroy]",
					async function (e) {
						console.log("Role delete clicked");
						await RoleManagement.destroy(e, roleGrid);
					}
				);

			$("button[name=createRole]", roleGrid.gridElement)
				.off("click.roleManagement")
				.on("click.roleManagement", async function (e) {
					await RoleManagement.createRole(e, app, roleGrid);
		});
	},

	save: async function (e, grid) {
		e.preventDefault();

		var role = grid.dataItem(
			$(e.currentTarget).closest("tr")
		);

		var payload = {
			Id: role.Id,
			AppId: role.AppId,
			Name: role.Name,
			Description: role.Description,
			Privs: role.Privs || ""
		};

		try {
			await api.put(
				"AppSecurity/Role(" + role.Id + ")",
				payload
			);

			notification.success(
				"[resource_displayname[RoleSaved]]"
			);

			await grid.refresh();
		} catch (err) {
			console.error(err);
			error(err);
		}
	},

	destroy: async function (e, grid) {
		e.preventDefault();

		var row = $(e.currentTarget).closest("tr");
		var role = grid.dataItem(row);

		try {
			await api.destroy(
				"AppSecurity/Role(" + role.Id + ")"
			);

			grid.dataSource().remove(role);

			notification.success(
				"[resource_displayname[roledeleted]]"
			);
		} catch (err) {
			error(err);
		}
	},

	expandRole: async function (e, app, grid, container) {
		var role = grid.dataItem(e.masterRow);
		var detailContainer = $(e.detailRow);
		var detailId = Guid();
		detailContainer.html(detailContainer.html().replaceAll("{ID}", detailId));
		if ($(detailContainer).find(".component").length == 0) {
			detailContainer.attr("data-component-loading", "true");
			var userHost = $("[name=userGrid]", detailContainer);
			var privHost = $("[name=privGrid]", detailContainer);
			var userComponent = $("[name=roleUserManagementComponent] > .component", container).first().clone();
			var privComponent = $("[name=rolePrivManagementComponent] > .component", container).first().clone();
			userComponent.find("script").remove();
			privComponent.find("script").remove();
			userHost.empty().append(userComponent);
			privHost.empty().append(privComponent);
			await RoleUserManagement.init(app, userComponent, role);
			await RolePrivManagement.init(app, privComponent, role);
			detailContainer.attr("data-component-loading", "false");
		}
	},

	createRole: async function (e, app, grid) {
		e.preventDefault();

		var createRoleDialog = new Dialog({
			width: Math.min(600, window.innerWidth - 40),
			height: "auto",
			title: "[resource_displayname[newRole]]"
		});

		createRoleDialog.template =
			$("script[name=\"newRoleDialog\"]", grid.element)
				.first()
				.html();

		createRoleDialog.events.create = async function (e) {
			e.preventDefault();

		var roleName = $("input[name=\"name\"]", createRoleDialog.element)
			.val()
			.trim();

		if (!roleName) {
			error("[resource_displayname[name]] is required.");
			return;
		}

		var role = {
			AppId: app.Id,
			Name: roleName,
			Privs: ""
		};

			try {
				await api.add("AppSecurity/Role", role);

				notification.success(
					"[resource_displayname[RoleCreated]]"
				);

				grid.refresh();
				createRoleDialog.events.close();
			} catch (err) {
				error(err);
			}
		};

		await createRoleDialog.init();
	}
}
